mapper.select:
SELECT g.id, g.name, g.owner_id,
       (SELECT COUNT(*) FROM im_group_message m FORCE INDEX (idx_group_history)
        WHERE m.group_id = g.id AND m.id > GREATEST(gm.joined_after_id, gm.last_read_id)
          AND m.sender_id != #{userId}) AS unread_count
FROM im_group_member gm JOIN im_chat_group g ON g.id = gm.group_id
WHERE gm.user_id = #{userId}
AND g.id < #{beforeId}
ORDER BY g.id DESC LIMIT #{limit}

SELECT id, group_id, sender_id, client_msg_id, body, created_at
FROM im_group_message
WHERE group_id = #{groupId} AND id = #{messageId} AND id > #{joinedAfterId}

SELECT id, group_id, sender_id, client_msg_id, body, created_at
FROM im_group_message FORCE INDEX (idx_group_history)
WHERE group_id = #{groupId} AND id > #{joinedAfterId}
AND id < #{beforeId}
ORDER BY id DESC LIMIT #{limit}

SELECT id, group_id, sender_id, client_msg_id, body, created_at
FROM im_group_message FORCE INDEX (idx_group_history)
WHERE group_id = #{groupId} AND id > #{joinedAfterId}
  AND body LIKE CONCAT('%', #{pattern}, '%') ESCAPE '='
AND id < #{beforeId}
ORDER BY id DESC LIMIT #{limit}
